{"cmd":"node --input-type=module <<'NODE'
import { execFileSync } from 'node:child_process';

const exe = '/workspace/dataset/test4_executable';
const cases = [
  ['extract_interval_cast', "select extract(year from current_date) as yr, interval '1 day' as step, cast(amount as decimal(12,4)) from sales"],
  ['case_coalesce', "select coalesce(name, 'unknown') as label, case when deleted_at is null then true else false end as active from users"],
  ['quoted_strings_like_keywords', "select 'select from where' as text, $$group by$$ as note from notes"],
  ['position_with_string', "select position('a' in name) from users"],
  ['type_names_select', "select 1::integer as i, 2::double precision as d, cast('x' as character varying(5)) as v"],
  ['like_ilike_similar', "select * from products where name like '%a%' or name ilike '%b%' or name similar to '(a|b)%'"],
  ['not_like_variants', "select * from products where name not like '%a%' and name not ilike '%b%'"],
  ['distinct_from', "select * from t where a is distinct from b or a is not distinct from c"],
  ['between_in_any_some', "select * from t where a between 1 and 2 and b in (1,2) and c = any (select d from u) and e = some (select f from v)"],
  ['cast_types', "select cast(1 as bigint), cast(1 as double precision), cast(1 as timestamp without time zone), cast(1 as timestamp with time zone)"],
  ['create_view_cte', "create view v as with x as (select 1 as from_col) select * from x"],
  ['identifier_plain_keywords', "select select_col, from_col, order_col from t"],
  ['alias_reserved_unquoted', "select amount as order, total as user from t order by order"],
  ['alias_reserved_quoted', "select amount as \"order\", total as \"user\" from t order by \"order\""],
  ['comment_preservation', "select a -- from where\nfrom t where b = 1"],
];

for (const [label, sql] of cases) {
  console.log(`CASE: ${label}`);
  console.log(`INPUT: ${JSON.stringify(sql)}`);
  try {
    const out = execFileSync(exe, ['--a', sql], { encoding: 'utf8' });
    process.stdout.write(out);
    if (!out.endsWith('\n')) process.stdout.write('\n');
    console.log('RC: 0');
  } catch (error) {
    if (error.stdout) process.stdout.write(error.stdout);
    if (error.stderr) process.stdout.write(error.stderr);
    console.log(`RC: ${error.status ?? 'ERR'}`);
  }
  console.log('');
}
